from django.utils import timezone


def anonymize_existing_ballots(apps, schema_editor):
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    VoterProfile = apps.get_model("voting", "VoterProfile")
    Participation = apps.get_model("voting", "Participation")
    Vote = apps.get_model("voting", "Vote")
    Election = apps.get_model("voting", "Election")

    for user in User.objects.all().iterator():
        VoterProfile.objects.get_or_create(
            user_id=user.pk,
            defaults={
                "role": "admin" if user.is_staff or user.is_superuser else "voter",
                "approval_status": "approved",
                "email_verified": True,
            },
        )

    for ballot in Vote.objects.all().iterator():
        Participation.objects.get_or_create(
            user_id=ballot.user_id,
            election_id=ballot.election_id,
            defaults={"voted_at": ballot.voted_at},
        )
        if ballot.receipt is None:
            ballot.receipt = uuid.uuid4()
            ballot.save(update_fields=("receipt",))

    Election.objects.filter(
        is_published=True,
        is_active=True,
        end_date__lt=timezone.now(),
        results_published_at__isnull=True,
    ).update(results_published_at=timezone.now())


